import binascii
import io
import gzip


def task_func(compressed_hex):
    """
    Decode a gzip-compressed hexadecimal string and return the decompressed
    UTF-8 text.

    Args:
        compressed_hex: Hexadecimal string representing gzip-compressed bytes.

    Returns:
        str: Decompressed UTF-8 string, or an error message.
    """
    try:
        if compressed_hex is None:
            return "Error: input is None"

        if not isinstance(compressed_hex, str):
            compressed_hex = str(compressed_hex)

        hex_str = compressed_hex.strip().replace(" ", "").replace("\n", "").replace("\r", "").replace("\t", "")
        if hex_str.startswith(("0x", "0X")):
            hex_str = hex_str[2:]

        if not hex_str:
            return "Error: empty input"

        compressed_bytes = binascii.unhexlify(hex_str)
        decoded_bytes = gzip.decompress(compressed_bytes)
        return decoded_bytes.decode("utf-8")

    except (binascii.Error, ValueError) as e:
        return f"Error: invalid hexadecimal input - {e}"
    except (OSError, EOFError) as e:
        return f"Error: invalid gzip data - {e}"
    except UnicodeDecodeError as e:
        return f"Error: output is not valid UTF-8 - {e}"
    except Exception as e:
        return f"Error: {e}"

