import urllib.request
from lxml import etree
import pandas as pd


def task_func(url):
    def _local_name(tag):
        if not isinstance(tag, str):
            return ""
        return tag.rsplit("}", 1)[-1] if "}" in tag else tag

    if not isinstance(url, str) or not url.strip():
        raise ValueError("Unable to fetch XML from URL.")

    try:
        with urllib.request.urlopen(url) as response:
            xml_bytes = response.read()
    except Exception as exc:
        raise ValueError("Unable to fetch XML from URL.") from exc

    try:
        root = etree.fromstring(xml_bytes)
    except etree.XMLSyntaxError as exc:
        raise ValueError("Invalid XML syntax.") from exc

    items = [elem for elem in root.iter() if _local_name(elem.tag) == "item"]
    if not items:
        raise ValueError("XML structure does not match expected format.")

    rows = []
    column_order = []
    seen_columns = set()

    for item in items:
        children = [child for child in item if isinstance(child.tag, str)]
        if not children:
            raise ValueError("XML structure does not match expected format.")

        row = {}
        seen_tags = set()

        for child in children:
            col_name = _local_name(child.tag)
            if not col_name or col_name in seen_tags:
                raise ValueError("XML structure does not match expected format.")

            seen_tags.add(col_name)
            if col_name not in seen_columns:
                seen_columns.add(col_name)
                column_order.append(col_name)

            row[col_name] = "".join(child.itertext()).strip()

        rows.append(row)

    if not rows:
        raise ValueError("XML structure does not match expected format.")

    return pd.DataFrame(rows).reindex(columns=column_order)

