import pytz
from dateutil.parser import parse
from datetime import timedelta

# Constants
TIME_FORMAT = "%d/%m/%y %H:%M:%S.%f"


def _localize_safely(tz, dt):
    """Localize a naive datetime while handling DST edge cases deterministically."""
    try:
        return tz.localize(dt, is_dst=None)
    except pytz.AmbiguousTimeError:
        # Prefer standard time for ambiguous fall-back timestamps.
        return tz.localize(dt, is_dst=False)
    except pytz.NonExistentTimeError:
        # Prefer the DST side for spring-forward gaps.
        try:
            return tz.localize(dt, is_dst=True)
        except Exception:
            return tz.localize(dt, is_dst=False)


def _format_milliseconds(dt):
    """Format datetime as dd/mm/yy HH:MM:SS.fff with rounding to milliseconds."""
    ms = (dt.microsecond + 500) // 1000
    if ms == 1000:
        dt = dt + timedelta(seconds=1)
        ms = 0
    return dt.strftime("%d/%m/%y %H:%M:%S.") + f"{ms:03d}"


def task_func(time_string, from_tz, to_tz):
    """
    Convert a time string from one timezone to another.

    Parameters
    ----------
    time_string : str
        Input time string.
    from_tz : str
        Source timezone name.
    to_tz : str
        Target timezone name.

    Returns
    -------
    str
        Converted time string in the format 'dd/mm/yy HH:MM:SS.fff'.
    """
    source_tz = pytz.timezone(from_tz)
    target_tz = pytz.timezone(to_tz)

    dt = parse(time_string)

    if dt.tzinfo is None:
        dt = _localize_safely(source_tz, dt)
    else:
        dt = dt.astimezone(source_tz)

    converted = dt.astimezone(target_tz)
    return _format_milliseconds(converted)

